<?php get_header();$collections=eph_collections();$total=array_sum(array_map(function($c){return ephemera_poc_count($c->ID);},$collections)); ?>
<main>
<section class="eph-home-intro"><p class="eph-eyebrow">Biblioteca e arquivo de José Pacheco Pereira</p><h1>Explore a memória<br>nos documentos.</h1><p>Cartazes, fotografias, publicações e testemunhos. Pesquise o acervo ou descubra as suas coleções.</p><?php eph_search_form('home-catalogue-search'); ?><div class="eph-home-summary"><span><strong><?php echo $total; ?></strong> registos no catálogo</span><span><strong><?php echo count($collections); ?></strong> coleções para explorar</span><a href="<?php echo esc_url(home_url('/catalogo/')); ?>">Ver todo o catálogo →</a></div></section>
<div class="eph-public-page eph-home-body">
<section><div class="eph-section-heading"><h2 class="eph-section-title">Descobrir o acervo</h2><a class="eph-more" href="<?php echo esc_url(home_url('/catalogo/')); ?>">Todos os registos →</a></div><div class="eph-catalogue-grid"><?php $featured=[];foreach($collections as $c){$items=ephemera_poc_items($c->ID);if($items)$featured[]=$items[0];}foreach(array_slice($featured,0,6) as $item)eph_item_card($item); ?></div></section>
<section class="eph-home-explore"><div><h2>Explorar por coleção</h2><p>Conheça a organização do acervo e encontre os documentos de cada conjunto.</p><a class="eph-more" href="<?php echo esc_url(home_url('/colecoes/')); ?>">Índice de coleções →</a></div><div><h2>Explorar por tema</h2><p>Relacione documentos de diferentes coleções através dos seus assuntos e contextos históricos.</p><div class="eph-topic-links"><?php foreach(eph_classifications() as $tax=>$group):foreach(array_slice($group['terms'],0,6) as $term): ?><a href="<?php echo esc_url(add_query_arg('tema',$tax.':'.$term->term_id,home_url('/catalogo/'))); ?>"><?php echo esc_html($term->name); ?> →</a><?php endforeach;endforeach; ?></div><a class="eph-more" href="<?php echo esc_url(home_url('/catalogo/')); ?>">Todos os filtros do catálogo →</a></div></section>
<section><div class="eph-section-heading"><h2 class="eph-section-title">Publicações do arquivo</h2><a class="eph-more" href="<?php echo esc_url(home_url('/publicacoes/')); ?>">Ver publicações →</a></div><?php foreach(get_posts(['post_type'=>'post','post_status'=>'publish','has_password'=>false,'numberposts'=>2]) as $entry): ?><article class="eph-editorial-row"><?php if(has_post_thumbnail($entry)): ?><a href="<?php echo esc_url(get_permalink($entry)); ?>"><?php echo get_the_post_thumbnail($entry,'medium_large',['loading'=>'lazy','alt'=>'']); ?></a><?php endif; ?><div><p class="eph-meta"><?php echo esc_html(get_the_date('j F Y',$entry)); ?></p><h3><a href="<?php echo esc_url(get_permalink($entry)); ?>"><?php echo esc_html($entry->post_title); ?></a></h3><a class="eph-more" href="<?php echo esc_url(get_permalink($entry)); ?>">Ler publicação →</a></div></article><?php endforeach; ?></section>
</div></main><?php get_footer(); ?>
